import type {BuildId} from '../../../../types'
import {FullLogTarget} from '../BuildLog.types'
import {parseExpandState} from '../BuildLog.utils'
import {updateFullLogState} from '../FullBuildLog/FullBuildLog.actions'

export const changePageFullLogBuildId = (buildId: BuildId | null | undefined) =>
  updateFullLogState({
    target: FullLogTarget.PAGE,
    buildId,
  })
export const resetPageFullLog = () =>
  updateFullLogState({
    target: FullLogTarget.PAGE,
    buildId: null,
    focusLine: null,
    expandState: null,
  })
export const setLinesState = (lines: string | null | undefined) =>
  updateFullLogState({
    target: FullLogTarget.PAGE,
    expandState: parseExpandState(lines) as ReadonlyArray<number> | null | undefined,
  })
export const setExpandAll = (value: boolean) =>
  updateFullLogState({
    target: FullLogTarget.PAGE,
    expandAll: value,
  })
export const setFocusLine = (focusLine: number | null | undefined) =>
  updateFullLogState({
    target: FullLogTarget.PAGE,
    focusLine: Number(focusLine) as number,
  })
