import {skipToken} from '@reduxjs/toolkit/query'
import {useCallback, useMemo} from 'react'
import * as React from 'react'
import {graphql} from 'react-relay'

import {useAppDispatch} from '../../../../../hooks/react-redux'
import {useRefetchableLazyLoadQuery} from '../../../../../hooks/relay/useRefetchableLazyLoadQuery'
import {useQueryParam} from '../../../../../hooks/routes'
import {getSingleBuildArg} from '../../../../../rest/builds'
import {getBuildLocator} from '../../../../../rest/locators'
import type {MatrixParameter} from '../../../../../services/rest'
import {restApi} from '../../../../../services/rest'
import type {MatrixDependencyParameter} from '../../../../../types'
import {toBuildId} from '../../../../../types'
import {emptyArray} from '../../../../../utils/empty'
import {getPropertyFromList} from '../../../../../utils/getProperty'
import {subscribeOnBuildTypesEvents} from '../../../../../utils/subscriber'
import {changePageFullLogBuildId} from '../../BuildLogTab/BuildLogTab.actions'

import type {useBuildLogBuildNavigationWrapperQuery} from './__generated__/useBuildLogBuildNavigationWrapperQuery.graphql'
import {
  BUILD_EVENT_TYPES,
  SELECTED_BUILD_DEPENDENCY_ID_PARAM,
} from './BuildLogBuildNavigationWrapper.consts'
import type {BuildLogBuildNavigationPropsItem} from './BuildLogBuildNavigationWrapper.types'

const query = graphql`
  query useBuildLogBuildNavigationWrapperQuery($buildLocator: String!) {
    build(buildLocator: $buildLocator) {
      matrixConfiguration {
        parameters {
          parameters {
            name
            value {
              value
              label
            }
          }
        }
        dependencies {
          dependency {
            build {
              id
              status
              buildType {
                internalId
              }
              state
            }
            parameters {
              entry {
                name
                value
              }
            }
          }
        }
      }
      snapshotDependencies(locator: "buildType:(project:(virtual:true))") {
        build {
          id
          status
          state
          buildType {
            internalId
          }
          properties(locator: "name:teamcity.build.parallelTests.currentBatch") {
            property {
              name
              value
            }
          }
        }
      }
    }
  }
`

function useBuildLogBuildNavigationWrapper(buildId: number) {
  const dispatch = useAppDispatch()
  const [{build}, refetch] = useRefetchableLazyLoadQuery<useBuildLogBuildNavigationWrapperQuery>(
    query,
    {buildLocator: getBuildLocator(buildId)},
  )
  const dependencies = build?.snapshotDependencies?.build ?? emptyArray
  const matrixConfiguration = build?.matrixConfiguration?.dependencies?.dependency ?? emptyArray
  const matrixParameters: readonly MatrixParameter[] =
    build?.matrixConfiguration?.parameters?.parameters ?? emptyArray
  const matrixConfigurationNamPosition = useMemo(
    () =>
      matrixParameters.reduce<Map<string, number>>((acc, parameter, index) => {
        if (parameter.name) {
          acc.set(parameter.name, index)
        }

        return acc
      }, new Map()),
    [matrixParameters],
  )
  const availableMatrixParametersMap = useMemo(
    () =>
      matrixParameters.reduce<Map<string, string | undefined | null>>((acc, parameter) => {
        if (parameter.value) {
          parameter.value.forEach(({value, label}) => acc.set(value ?? '', label))
        }
        return acc
      }, new Map()),
    [matrixParameters],
  )
  const pageFullLogBuildIdParam = useQueryParam(SELECTED_BUILD_DEPENDENCY_ID_PARAM)
  const selectedNavigationId =
    pageFullLogBuildIdParam != null ? toBuildId(pageFullLogBuildIdParam) : null
  const getmatrixConfigurationButtonName = useCallback(
    (parameters: MatrixDependencyParameter[]) =>
      parameters
        .sort((current, previous) => {
          const {name: currentName = ''} = current
          const {name: previousName = ''} = previous
          const currentPosition = matrixConfigurationNamPosition.get(currentName) ?? 0
          const previousPosition = matrixConfigurationNamPosition.get(previousName) ?? 0

          return currentPosition - previousPosition
        })
        .map(({value = ''}) => availableMatrixParametersMap.get(value) ?? value)
        .join(', '),
    [availableMatrixParametersMap, matrixConfigurationNamPosition],
  )
  const matrixConfigurationLogNavigationItems = useMemo(
    () =>
      matrixConfiguration.reduce<BuildLogBuildNavigationPropsItem[]>(
        (acc, {build: {buildType, status, state, id}, parameters}) => {
          const name = getmatrixConfigurationButtonName([...parameters.entry])

          acc.push({
            status,
            state,
            id,
            name,
            internalId: buildType?.internalId,
          })

          return acc
        },
        [],
      ),
    [getmatrixConfigurationButtonName, matrixConfiguration],
  )
  const dependenciesLogNavigationItems = useMemo(
    () =>
      dependencies.reduce<BuildLogBuildNavigationPropsItem[]>(
        (acc, {status, state, id, properties, buildType}) => {
          const index = getPropertyFromList('teamcity.build.parallelTests.currentBatch', properties)
          const hasMatrixConfiguration =
            matrixConfigurationLogNavigationItems.find(
              ({internalId}) => internalId === buildType?.internalId,
            ) != null

          if (index && !hasMatrixConfiguration) {
            acc.push({
              status,
              state,
              id,
              name: `Batch ${index}`,
              internalId: buildType?.internalId,
            })
          }

          return acc
        },
        [],
      ),
    [dependencies, matrixConfigurationLogNavigationItems],
  )

  const commonLogNavigationItems = useMemo(
    () => [...dependenciesLogNavigationItems, ...matrixConfigurationLogNavigationItems],
    [dependenciesLogNavigationItems, matrixConfigurationLogNavigationItems],
  )

  restApi.endpoints.getBuildNormalized.useQuerySubscription(
    selectedNavigationId != null
      ? getSingleBuildArg(getBuildLocator(selectedNavigationId))
      : skipToken,
  )

  React.useEffect(() => {
    if (commonLogNavigationItems.length) {
      return subscribeOnBuildTypesEvents(
        commonLogNavigationItems.map(({internalId}) => internalId),
        BUILD_EVENT_TYPES,
        refetch,
      )
    }
    return undefined
  }, [commonLogNavigationItems, refetch])

  React.useEffect(() => {
    if (selectedNavigationId != null) {
      dispatch(changePageFullLogBuildId(selectedNavigationId))
    } else {
      dispatch(changePageFullLogBuildId(buildId))
    }
  }, [buildId, dispatch, selectedNavigationId])

  return {
    commonLogNavigationItems,
  }
}

export default useBuildLogBuildNavigationWrapper
