import searchIcon from '@jetbrains/icons/search.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Input from '@jetbrains/ring-ui-built/components/input/input'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import {useContext} from 'react'

import {isPipelinesScreen} from '../../../../../../routes'
import type {BuildId} from '../../../../../../types'
import {isKey} from '../../../../../../utils/guards'
import {cmdOrCtrlPlus} from '../../../../../../utils/keys'
import {buildLogSearchHint} from '../../../../Hints/HintItems/Hints.buildOverview'
import {stringifyHintId} from '../../../../Hints/Hints.types'
import {FullLogTarget} from '../../../BuildLog.types'
import BuildLogFilterMenu, {filterLabels} from '../../BuildLogFilterMenu/BuildLogFilterMenu'
import {TargetContext} from '../../FullBuildLog.context'

import useBuildLogControls from './BuildLogControls.hooks'
import DownloadBuildLogDropdown from './DownloadBuildLogDropdown/DownloadBuildLogDropdown'
import ViewToggle from './ViewToggle/ViewToggle'

import styles from './BuildLogControls.module.css'

type Props = {
  buildId: BuildId
  setSearchActive: (searchActive: boolean) => unknown
}

function BuildLogControls({buildId, setSearchActive}: Props) {
  const target = useContext(TargetContext)
  const {
    filterValue,
    searchEnabled,
    messagesExists,
    showSearch,
    onExpandAllClick,
    onCollapseAllClick,
    onToggleFullscreen,
  } = useBuildLogControls(setSearchActive, buildId)
  const isShowFullScreenButton =
    target !== FullLogTarget.POPUP && !isPipelinesScreen(location.pathname)

  return (
    <div className={styles.controls}>
      <IconButton
        withBorder
        className={styles.foldButton}
        onClick={onExpandAllClick}
        disabled={!messagesExists}
        data-test-full-build-log={'expand'}
        icon="unfold-more-12px"
        title="Expand all"
      />
      <IconButton
        withBorder
        className={styles.foldButton}
        onClick={onCollapseAllClick}
        disabled={!messagesExists}
        data-test-full-build-log={'collapse'}
        icon="unfold-less-12px"
        title="Collapse all"
      />
      {searchEnabled && (
        <Input
          className={styles.searchContainer}
          inputClassName={styles.search}
          data-hint-container-id={stringifyHintId(buildLogSearchHint.id)}
          onFocus={showSearch}
          disabled={!messagesExists}
          data-test-full-build-log={'open-search'}
          type="search"
          placeholder={`Search (${cmdOrCtrlPlus}F)`}
          icon={searchIcon}
        />
      )}
      <div className={styles.controlsButton} data-test-full-build-log="controls">
        <Dropdown
          anchor={
            <Button disabled={!messagesExists} data-test-full-build-log={'filter'} dropdown>
              {`${
                filterValue && isKey(filterLabels, filterValue)
                  ? filterLabels[filterValue]
                  : filterLabels.all
              } `}
            </Button>
          }
        >
          <BuildLogFilterMenu />
        </Dropdown>
        <ViewToggle />
        <DownloadBuildLogDropdown buildId={buildId} />

        {isShowFullScreenButton && (
          <IconButton title="Enter full screen" icon="expand-all" onClick={onToggleFullscreen} />
        )}
      </div>
    </div>
  )
}

export default BuildLogControls
