import classNames from 'classnames'
import {memo, useContext, useEffect, useState} from 'react'

import type {BuildId} from '../../../../../types'
import {
  PipelinesTarget,
  PipelinesTargetContext,
} from '../../../../pages/PipelinesPages/contexts/targetContext'
import {FullLogTarget} from '../../BuildLog.types'
import BuildLogTimeline from '../../BuildLogTimeline/BuildLogTimeline.container'
import {TargetContext} from '../FullBuildLog.context'

import BuildLogControls from './BuildLogControls/BuildLogControls'
import BuildLogSearch from './BuildLogSearch/BuildLogSearch'

import styles from './BuildLogCompactHeader.module.css'

type Props = {
  buildId: BuildId
}

function BuildLogCompactHeader({buildId}: Props) {
  const target = useContext(TargetContext)
  const pipelinesTarget = useContext(PipelinesTargetContext)
  const [searchActive, setSearchActive] = useState(false)
  const isShowLogTimeline =
    pipelinesTarget !== PipelinesTarget.JOB_DETAILS_SIDEBAR &&
    pipelinesTarget !== PipelinesTarget.JOB_DETAILS_POPUP &&
    pipelinesTarget !== PipelinesTarget.JOB_DEBUG_PANEL

  useEffect(() => setSearchActive(false), [buildId])

  return (
    <div
      className={classNames(styles.header, {
        [styles.jobDetailsPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP,
        [styles.jobDetailsSidebarTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR,
        [styles.jobDebugPanelTarget]: pipelinesTarget === PipelinesTarget.JOB_DEBUG_PANEL,
        [styles.jobDebugPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DEBUG_POPUP,
      })}
    >
      {searchActive ? (
        <BuildLogSearch setSearchActive={setSearchActive} />
      ) : (
        <BuildLogControls buildId={buildId} setSearchActive={setSearchActive} />
      )}
      {isShowLogTimeline && (
        <div
          className={classNames(styles.headerTimeline, {
            [styles.targetPage]: target === FullLogTarget.POPUP,
          })}
        >
          <BuildLogTimeline buildId={buildId} logTarget={target} />
        </div>
      )}
    </div>
  )
}

export default memo(BuildLogCompactHeader)
