import {memo, useEffect} from 'react'

import {useAppDispatch} from '../../../../hooks/react-redux'
import {useQueryParam} from '../../../../hooks/routes'
import {toBuildId} from '../../../../types'
import {SELECTED_BUILD_DEPENDENCY_ID_PARAM} from '../FullBuildLog/BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper.consts'

import BuildLogTab from './BuildLogTab'
import {changePageFullLogBuildId, resetPageFullLog} from './BuildLogTab.actions'
import type {Props} from './BuildLogTab.types'

function BuildLogTabContainer({className, buildId}: Props) {
  const dispatch = useAppDispatch()
  const pageFullLogBuildIdParam = useQueryParam(SELECTED_BUILD_DEPENDENCY_ID_PARAM)
  const selectedNavigationId =
    pageFullLogBuildIdParam != null ? toBuildId(pageFullLogBuildIdParam) : null

  useEffect(() => {
    dispatch(changePageFullLogBuildId(selectedNavigationId ?? buildId))
    return () => {
      dispatch(resetPageFullLog())
    }
  }, [dispatch, buildId, selectedNavigationId])

  return <BuildLogTab buildId={buildId} className={className} />
}

export default memo(BuildLogTabContainer)
