import Measure from '../../../../../containers/Measure'
import type {BuildId} from '../../../../../types'
import BuildLogBuildNavigation from '../BuildLogBuildNavigation/BuildLogBuildNavigation'

import useBuildLogBuildNavigationWrapper from './useBuildLogBuildNavigationWrapper'

type BuildLogBuildNavigationWrapperProps = {
  buildId: BuildId
  className?: string
}

function BuildLogBuildNavigationWrapper({buildId, className}: BuildLogBuildNavigationWrapperProps) {
  const {commonLogNavigationItems} = useBuildLogBuildNavigationWrapper(buildId)

  return (
    <Measure client>
      {({measureRef, contentRect}) => {
        const width = contentRect.client?.width

        return (
          <div ref={measureRef}>
            <BuildLogBuildNavigation
              width={width}
              buildId={buildId}
              items={commonLogNavigationItems}
              className={className}
            />
          </div>
        )
      }}
    </Measure>
  )
}

export default BuildLogBuildNavigationWrapper
