import type {ComponentType} from 'react'
import {connect} from 'react-redux'

import type {State} from '../../../../../reducers/types'
import {getBuildLogMessagesReady, getFullLogState} from '../../BuildLog.selectors'
import {getKeyForBuildLogData} from '../../BuildLog.utils'
import {navigateToFirstMessage, navigateToLastMessage} from '../FullBuildLog.actions'

import BuildLogNavigation from './BuildLogNavigation'
import type {OwnProps, StateProps, ActionProps} from './BuildLogNavigation.types'

const actionCreators: ActionProps = {
  navigateToFirstMessage,
  navigateToLastMessage,
}

const mapStateToProps = (state: State, {target, buildId}: OwnProps): StateProps => {
  const {showedFirstId, showedLastId, messagesExists} = getFullLogState(state, target)
  const buildLogKey = getKeyForBuildLogData({
    type: 'full',
    target,
    id: buildId,
  })
  return {
    ready: getBuildLogMessagesReady(state, buildLogKey),
    showedFirstId,
    showedLastId,
    messagesExists,
  }
}

export default connect(
  mapStateToProps,
  actionCreators,
)(BuildLogNavigation) as ComponentType<OwnProps>
