import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import DropdownMenu from '@jetbrains/ring-ui-built/components/dropdown-menu/dropdown-menu'
import {ListProps} from '@jetbrains/ring-ui-built/components/popup-menu/popup-menu'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {useContext} from 'react'

import {stringifyId} from '../../../../../types'
import {
  PipelinesTarget,
  PipelinesTargetContext,
} from '../../../../pages/PipelinesPages/contexts/targetContext'
import type {BuildLogBuildNavigationProps} from '../BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper.types'

import useBuildLogBuildNavigation from './useBuildLogBuildNavigation'

import styles from './BuildLogBuildNavigation.module.css'

const MIN_WIDTH_CONTAINER = 820

function BuildLogBuildNavigationStatusIcon({status, state}: {status: string; state: string}) {
  return status === 'SUCCESS' && state === 'finished' ? (
    <SvgIcon className={styles.successIcon} icon="ok" />
  ) : status === 'FAILURE' ? (
    <SvgIcon className={styles.failureIcon} icon="exception" />
  ) : status === 'UNKNOWN' ? (
    <SvgIcon className={styles.failureIcon} icon="cancel" />
  ) : null
}

function BuildLogBuildNavigation({
  buildId,
  items,
  width = MIN_WIDTH_CONTAINER,
  className,
}: BuildLogBuildNavigationProps) {
  const {
    sortedItems,
    isShowDropdownMenu,
    selectedItemId,
    numberButtonLimit,
    selectNavigationButtonClick,
  } = useBuildLogBuildNavigation(items, buildId, width)
  const pipelinesTarget = useContext(PipelinesTargetContext)

  return (
    <div
      className={classNames(styles.container, className, {
        [styles.jobDetailsPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP,
        [styles.jobDetailsSidebarTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR,
      })}
    >
      <ButtonGroup className={styles.buttonGroup}>
        <Button
          active={selectedItemId == null || buildId === selectedItemId}
          onClick={selectNavigationButtonClick(undefined)}
        >
          {'Current build'}
        </Button>
        {sortedItems.slice(0, numberButtonLimit).map(({state, id, status, name}) => (
          <Button
            active={selectedItemId != null && id === selectedItemId}
            key={id}
            title={name}
            onClick={selectNavigationButtonClick(stringifyId(id))}
            className={classNames(styles.button, {[styles.failedBuild]: status === 'FAILURE'})}
          >
            <BuildLogBuildNavigationStatusIcon status={status} state={state} />
            {name}
          </Button>
        ))}
        {isShowDropdownMenu && (
          <DropdownMenu
            data={sortedItems.slice(numberButtonLimit).map(({id, status, state, name}) => ({
              className: status === 'FAILURE' ? styles.failedBuild : undefined,
              rgItemType: ListProps.Type.CUSTOM,
              template: (
                <>
                  <BuildLogBuildNavigationStatusIcon status={status} state={state} />
                  {name}
                </>
              ),
              onClick: selectNavigationButtonClick(stringifyId(id)),
            }))}
            anchor={<Button>{'...'}</Button>}
          />
        )}
      </ButtonGroup>
    </div>
  )
}

export default BuildLogBuildNavigation
