import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import classNames from 'classnames'
import type {ContextType} from 'react'
import {PureComponent} from 'react'

import {cmdOrCtrl} from '../../../../../utils/keys'
import {
  PipelinesTarget,
  PipelinesTargetContext,
} from '../../../../pages/PipelinesPages/contexts/targetContext'

import type {Props} from './BuildLogNavigation.types'
import BuildLogNavigationButton from './BuildLogNavigationButton/BuildLogNavigationButton'

import styles from './BuildLogNavigation.module.css'

class BuildLogNavigation extends PureComponent<Props> {
  static contextType = PipelinesTargetContext

  declare context: ContextType<typeof PipelinesTargetContext>

  onGoFirstClick: () => void = () => {
    const {navigateToFirstMessage, target} = this.props
    navigateToFirstMessage(target)
  }

  onGoLastClick: () => void = () => {
    const {navigateToLastMessage, target} = this.props
    navigateToLastMessage(target)
  }

  render() {
    const {showedFirstId, showedLastId, startMessageId, finishMessageId, messagesExists, ready} =
      this.props
    const startShown = startMessageId != null && showedFirstId === startMessageId
    const finishShown = finishMessageId != null && showedLastId === finishMessageId

    const isPipelineContext =
      this.context === PipelinesTarget.JOB_DETAILS_POPUP ||
      this.context === PipelinesTarget.JOB_DETAILS_SIDEBAR ||
      this.context === PipelinesTarget.JOB_DEBUG_POPUP ||
      this.context === PipelinesTarget.JOB_DEBUG_PANEL

    return (
      <div
        className={classNames(styles.navigation, {
          [styles.pipelineTarget]: isPipelineContext,
        })}
      >
        <ButtonGroup split className={styles.buttons}>
          <BuildLogNavigationButton
            disabled={!messagesExists || !ready || startShown || showedFirstId == null}
            icon={isPipelineContext ? 'chevron-up' : null}
            label="Scroll to top"
            hint={`Home or ${cmdOrCtrl}↑`}
            className={classNames(styles.button, styles.start)}
            onClick={this.onGoFirstClick}
          />
          <BuildLogNavigationButton
            disabled={!messagesExists || !ready || finishShown || showedLastId == null}
            icon={isPipelineContext ? 'chevron-down' : null}
            label="To bottom"
            hint={`End or ${cmdOrCtrl}↓`}
            className={classNames(styles.button, styles.end)}
            onClick={this.onGoLastClick}
          />
        </ButtonGroup>
      </div>
    )
  }
}

export default BuildLogNavigation
