import {useMemo} from 'react'

import {useQueryParam, useSetQueryParams} from '../../../../../hooks/routes'
import type {BuildId} from '../../../../../types'
import {toBuildId} from '../../../../../types'
import {SELECTED_BUILD_DEPENDENCY_ID_PARAM} from '../BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper.consts'
import type {BuildLogBuildNavigationPropsItem} from '../BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper.types'

function useBuildLogBuildNavigation(
  items: BuildLogBuildNavigationPropsItem[],
  buildId: BuildId,
  width: number,
) {
  const itemsLength = items.length
  const setQueryParams = useSetQueryParams()
  const pageFullLogBuildIdParam = useQueryParam(SELECTED_BUILD_DEPENDENCY_ID_PARAM)
  const selectedItemId = pageFullLogBuildIdParam != null ? toBuildId(pageFullLogBuildIdParam) : null
  const selectNavigationButtonClick = (id?: string) => () =>
    setQueryParams({[SELECTED_BUILD_DEPENDENCY_ID_PARAM]: id})
  const numberButtonLimit = useMemo(() => {
    const buttonMoreWidth = 42
    const buttonCurrentWidth = 106
    const buttonDefaultIndent = 54
    const averageСharacterWidth = 11
    const remainingWidth = width - buttonCurrentWidth - buttonMoreWidth
    let buttonIndex = 0
    let buttonSizes = 0

    for (; buttonIndex < itemsLength; buttonIndex++) {
      const {name} = items[buttonIndex]
      const nameLength = name.length
      const buttonSize = nameLength * averageСharacterWidth + buttonDefaultIndent

      if (buttonSizes > remainingWidth) {
        return buttonIndex
      }

      buttonSizes += buttonSize
    }

    return undefined
  }, [items, itemsLength, width])
  const isShowDropdownMenu = numberButtonLimit ? items.length > numberButtonLimit : false
  const sortedItems = useMemo(() => {
    let sortedMatrixConfiguration = items
    if (selectedItemId != null) {
      const selectedDependencyIndex = items.findIndex(({id}) => id === selectedItemId)

      if (
        selectedDependencyIndex !== -1 &&
        numberButtonLimit &&
        selectedDependencyIndex > numberButtonLimit - 1
      ) {
        const dependenciesCopy = items.slice()
        const [selectedDependency] = dependenciesCopy.splice(selectedDependencyIndex, 1)

        sortedMatrixConfiguration = [
          ...dependenciesCopy.slice(0, numberButtonLimit - 1),
          selectedDependency,
          ...dependenciesCopy.slice(numberButtonLimit - 1),
        ]
      }
    }

    return sortedMatrixConfiguration
  }, [items, numberButtonLimit, selectedItemId])

  return {
    sortedItems,
    selectedItemId,
    numberButtonLimit,
    isShowDropdownMenu,
    selectNavigationButtonClick,
  }
}

export default useBuildLogBuildNavigation
