import classNames from 'classnames'
import {useContext} from 'react'

import {getBuild} from '../../../../selectors'
import {
  PipelinesTarget,
  PipelinesTargetContext,
} from '../../../pages/PipelinesPages/contexts/targetContext'
import {getFullLogState} from '../BuildLog.selectors'
import {FullLogTarget} from '../BuildLog.types'
import BuildLogBuildNavigationWrapper from '../FullBuildLog/BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper'
import FullBuildLog from '../FullBuildLog/FullBuildLog.container'

import type {Props} from './BuildLogTab.types'

import styles from './BuildLogTab.module.css'

import {useAppSelector} from 'src/hooks/react-redux'

export default function BuildLogTab({className, buildId}: Props) {
  const pipelinesTarget = useContext(PipelinesTargetContext)
  const parallelized = useAppSelector(state => getBuild(state, buildId)?.parallelized)
  const matrixConfiguration = useAppSelector(
    state => getBuild(state, buildId)?.matrixConfiguration?.enabled,
  )
  const storedBuildId = useAppSelector(state => getFullLogState(state, FullLogTarget.PAGE).buildId)
  const isShowLogNavigation = parallelized || matrixConfiguration
  const pipelinesNavigation =
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_POPUP ||
    pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_POPUP ||
    pipelinesTarget === PipelinesTarget.JOB_DEBUG_PANEL

  if (storedBuildId == null) {
    return null
  }

  return (
    <div
      className={classNames(styles.page, className, {
        [styles.jobDetailsSidebarTarget]: pipelinesTarget === PipelinesTarget.JOB_DETAILS_SIDEBAR,
        [styles.jobDebugPanelTarget]: pipelinesTarget === PipelinesTarget.JOB_DEBUG_PANEL,
        [styles.jobDebugPopupTarget]: pipelinesTarget === PipelinesTarget.JOB_DEBUG_POPUP,
      })}
    >
      {isShowLogNavigation && !pipelinesNavigation && (
        <BuildLogBuildNavigationWrapper buildId={buildId} />
      )}
      <FullBuildLog key={buildId} target={FullLogTarget.PAGE} className={styles.log} />
    </div>
  )
}
